/** Standard Google polyline encoding, so buildRoute does its real decode/trim work. */
function encode(points: [number, number][]): string {
  let out = "", prevLat = 0, prevLng = 0;
  const chunk = (v: number): string => {
    let n = v < 0 ? ~(v << 1) : v << 1;
    let s = "";
    while (n >= 0x20) { s += String.fromCharCode((0x20 | (n & 0x1f)) + 63); n >>= 5; }
    return s + String.fromCharCode(n + 63);
  };
  for (const [lat, lng] of points) {
    const la = Math.round(lat * 1e5), ln = Math.round(lng * 1e5);
    out += chunk(la - prevLat) + chunk(ln - prevLng);
    prevLat = la; prevLng = ln;
  }
  return out;
}

